INSERT INTO `node_revision__field_content` VALUES
('sections',0,2,16,'en',0,'<div classname=\"container mx-auto px-4\"><div classname=\"flex flex-col md:flex-row items-stretch\"><p>{/* START column (left in English, right in Arabic) */}</p><div classname=\"md:w-1/2 p-2 py-4 sm:p-6 lg:p-8 flex flex-col\"><div classname=\"box box-green px-6 py-10 md:px-8 md:py-12\"><h3 classname=\"font-bold sub-title\">About EWA</h3><h2 classname=\"font-bold title\">Academy for Quality</h2><div classname=\"spacer-40\">&nbsp;</div><p classname=\"\">We Are a Non-Profit Training Academy That Offers High-Quality Technical Training and Vocational Education Focused on Water, Energy and Other Related Industrial Fields.</p><div classname=\"spacer-40\">&nbsp;</div><div classname=\"flex justify-start\"><arrowlink href=\"/about\">Learn More</arrowlink></div></div><div classname=\"spacer-40\">&nbsp;</div><div classname=\"box box-orange px-6 py-10 md:px-8 md:py-12\"><h2 classname=\"font-bold title\">Success Partner</h2><div classname=\"spacer-40\">&nbsp;</div><p>Leading the Way in Training and Developing Our National Workforce</p><div classname=\"spacer-40\">&nbsp;</div><div classname=\"flex justify-end\"><arrowlink href=\"/contact\" color=\"orange\" classname=\"ms-auto\">Send a Request</arrowlink></div></div></div><p>{/* END column */}</p><div classname=\"md:w-1/2 p-2 py-4 sm:p-6 lg:p-8 flex\"><div classname=\"box box-mixed p-8 bg-[url(http://localhost/ewa/sites/default/files/2026-10/home-about-bg.jpg)] bg-cover bg-center w-full flex min-h-[320px]\"><div classname=\"flex flex-row w-full gap-4\"><div classname=\"w-1/2 prog\"><div classname=\"flex flex-col justify-end h-full text-center\"><p classname=\"counter\">20</p><p>Diploma Programs</p></div></div><div classname=\"w-1/2 prog\"><div classname=\"flex flex-col justify-end h-full text-center\"><p classname=\"counter\">70</p><p>Sponsorship Partners</p></div></div></div></div></div></div></div><p>{/* centre emblem — only where the two columns sit side by side */} <img src=\"http://localhost/ewa/si